'use client';

import { keepPreviousData, useQuery } from '@tanstack/react-query';
import { QueryKeys } from '@/constants/query-keys';
import { useUserInfoStore } from '@/store/userInfo';
import { useMemo } from 'react';
import { fetchCrmBoard, fetchCrmBoardAllPages } from '../services';
import type { CrmBoardParams } from '../services';
import type { CrmFilters } from '../types';
import { buildDueFaseRqlCondition, flattenBoardTasks, sanitizeCrmRqlLiteral } from '../utils';

export { sanitizeCrmRqlLiteral } from '../utils';

/**
 * Monta o `query=` RQL dual-layer (milestone + task) esperado por
 * /api/crm/marcos-tasks/ — ver crm_marcos_tasks_rql_frontend.md.
 *
 * Campos de marco (`origin_type`, `creditor`, `status_liquidacao`, …) recortam
 * os itens `type=milestone` e removem as tarefas avulsas do stream; campos de
 * tarefa (`status`, `priority`, `assignee`) filtram as tarefas aninhadas e
 * derrubam o marco que ficar sem nenhuma.
 */
export function buildCrmBoardRqlQuery(filters: CrmFilters): string | undefined {
  const conditions: string[] = [];

  if (filters.marcoOrigemTipo) {
    const originType = sanitizeCrmRqlLiteral(filters.marcoOrigemTipo);
    if (originType) conditions.push(`eq(origin_type,${originType})`);
  }
  if (filters.marcoCredor) {
    const creditor = sanitizeCrmRqlLiteral(filters.marcoCredor);
    if (creditor) conditions.push(`ilike(creditor,*${creditor}*)`);
  }
  if (filters.marcoEmLitigio !== null) {
    conditions.push(`eq(in_litigation,${filters.marcoEmLitigio})`);
  }
  if (filters.marcoHasTasks !== null) {
    conditions.push(`eq(hasTasks,${filters.marcoHasTasks})`);
  }
  // Vínculo da tarefa com marco (crm_rql_has_marco.md): `false` deixa o stream
  // só com `type=task` (órfãs); `true`, só com `type=milestone`. Combinado com
  // qualquer filtro de marco o backend devolve `items: []` — o FilterBar impede
  // a combinação em vez de deixar a lista vazia sem explicação.
  if (filters.taskHasMarco !== null) {
    conditions.push(`eq(has_marco,${filters.taskHasMarco})`);
  }
  // Recorte "Liquidação/Cessão": o board expõe `status_liquidacao` na camada de
  // marco, então a fase da Due não precisa mais de fallback client-side aqui.
  const dueFaseRql = buildDueFaseRqlCondition(filters.marcoDueFase);
  if (dueFaseRql) conditions.push(dueFaseRql);
  if (filters.marcoId) {
    const milestoneId = sanitizeCrmRqlLiteral(filters.marcoId);
    if (milestoneId) conditions.push(`eq(milestone_id,${milestoneId})`);
  }
  if (
    filters.status &&
    filters.status !== 'TODOS' &&
    filters.status !== 'ATRASADA' &&
    filters.status !== 'DELEGADA'
  ) {
    const status = sanitizeCrmRqlLiteral(filters.status);
    if (status) conditions.push(`eq(status,${status})`);
  }
  if (filters.priority) {
    const priority = sanitizeCrmRqlLiteral(filters.priority);
    if (priority) conditions.push(`eq(priority,${priority})`);
  }
  if (filters.assigneeId) {
    const assignee = sanitizeCrmRqlLiteral(filters.assigneeId);
    if (assignee) conditions.push(`eq(assignee,${assignee})`);
  }

  if (conditions.length === 0) return undefined;
  if (conditions.length === 1) return conditions[0];
  return `and(${conditions.join(',')})`;
}

export function useCrmBoard(params: CrmBoardParams, options?: { enabled?: boolean }) {
  const userSessionData = useUserInfoStore((state) => state.data);

  return useQuery({
    queryKey: [QueryKeys.uniflowCrm.board, params],
    queryFn: () => fetchCrmBoard(params),
    enabled: (options?.enabled ?? true) && !!userSessionData,
    placeholderData: keepPreviousData,
  });
}

/**
 * Tarefas de um recorte inteiro do board, achatadas e sem paginação de servidor.
 *
 * Serve a aba Tarefas quando o filtro depende de um campo que só existe na
 * camada de marco do board — hoje `status_liquidacao` (origem
 * "Liquidação/Cessão"), que `GET /api/crm/tasks/` não conhece. Como o stream é
 * paginado por marco, a busca varre todas as páginas de uma vez
 * (`fetchCrmBoardAllPages`) e a paginação da aba passa a ser client-side.
 */
export function useCrmBoardTasks(filters: CrmFilters, options?: { enabled?: boolean }) {
  const userSessionData = useUserInfoStore((state) => state.data);
  const rqlQuery = useMemo(() => buildCrmBoardRqlQuery(filters), [filters]);

  // Sem `includeArchived`: a aba Tarefas é lista de trabalho, arquivadas
  // (`PAUSADO`) ficam de fora — a chave reflete isso para não colidir com o
  // board paginado da aba Tudo, que as inclui.
  const query = useQuery({
    queryKey: [QueryKeys.uniflowCrm.board, 'all', { query: rqlQuery, includeArchived: false }],
    queryFn: () => fetchCrmBoardAllPages({ query: rqlQuery }),
    enabled: (options?.enabled ?? true) && !!userSessionData,
    placeholderData: keepPreviousData,
  });

  const tasks = useMemo(
    () => flattenBoardTasks(query.data?.results.items ?? []),
    [query.data],
  );

  return {
    tasks,
    isSuccess: query.isSuccess,
    isLoading: query.isLoading,
    isFetching: query.isFetching,
    isError: query.isError,
  };
}

